//! The on-disk fixtures generated by scripts/gen_fixtures.py must load.

use manifest_selector::loader;
use manifest_selector::store::Store;

fn fixtures_root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures")
}

#[test]
fn loads_generated_fixtures() {
    let mut store = Store::new();
    let repos = loader::load_dir(&mut store, &fixtures_root()).unwrap();
    for expected in [
        "demo-multiarch",
        "demo-ambiguous",
        "demo-nested",
        "demo-missing",
    ] {
        assert!(repos.contains(&expected.to_string()), "missing {expected}");
    }

    // Every tag must resolve to a stored, digest-verified blob.
    for name in &repos {
        let repo = store.repo(name).unwrap();
        for (tag, digest) in &repo.tags {
            assert!(
                repo.blobs.contains_key(digest),
                "{name}:{tag} -> {digest} has no blob"
            );
            let parsed = manifest_selector::digest::Digest::parse(digest).unwrap();
            store.get(name, &parsed).expect("tagged blob must verify");
        }
    }
}

#[test]
fn missing_directory_is_empty_not_fatal() {
    let mut store = Store::new();
    let repos = loader::load_dir(&mut store, std::path::Path::new("/nonexistent-xyz")).unwrap();
    assert!(repos.is_empty());
}
